var i=[{title:`Perché la bilancia si muove`,text:`Cibo e bevande, idratazione, sodio, glicogeno immagazzinato e altri processi normali spostano il tuo peso corporeo da un giorno all’altro. Una lettura alta o bassa non ti dice nulla di affidabile su muscolo o grasso. L’esercizio può cambiare la tua composizione corporea anche quando il peso totale si muove appena.`},{title:`Misura sempre allo stesso modo`,text:`Se ti pesi, usa la stessa bilancia e una routine simile invece di orari casuali. Una media settimanale è spesso più utile di una singola lettura. Vita e altre misure con il metro sono confrontabili solo se usi gli stessi punti di riferimento del corpo e la stessa tensione del metro.`},{title:`Le foto sono facoltative`,text:`Le foto dei progressi possono mostrare cambiamenti di postura o di aspetto, ma luce, angolazione della fotocamera e abbigliamento le influenzano molto. Non ti servono se il tuo obiettivo è la forma fisica o la forza, e possono non aiutare se hai preoccupazioni sull’immagine corporea o sull’alimentazione.`},{title:`Forma fisica e peso sono separati`,text:`Muoversi meglio, durare di più e diventare più forti sono risultati reali qualunque sia la tua corporatura. Se sei preoccupato per un cambiamento di peso inatteso o per una condizione medica, parlane con un professionista sanitario.`},{title:`Usare TrainUp`,text:`La Dashboard ha un registro del peso corporeo, e usarlo o no dipende da te. Leggilo come una tendenza nell’arco di diverse settimane. TrainUp non tratta il peso corporeo come una misura della forma fisica e non fissa obiettivi di perdita di peso.`}];var a=[{label:`CDC: peso sano e attività fisica`,url:`https://www.cdc.gov/healthy-weight-growth/losing-weight/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:i,sources:a};export{t as default,i as sections,a as sources};